class Solution {
    public double findMedianSortedArrays(int[] nums1, int[] nums2) {
        int total = nums1.length + nums2.length;
        int[] merged = new int[total];
        int first = 0;
        int second = 0;
        int write = 0;
        while (first < nums1.length && second < nums2.length) {
            if (nums1[first] <= nums2[second]) {
                merged[write++] = nums1[first++];
            } else {
                merged[write++] = nums2[second++];
            }
        }
        while (first < nums1.length) merged[write++] = nums1[first++];
        while (second < nums2.length) merged[write++] = nums2[second++];
        int middle = total / 2;
        if (total % 2 == 1) return merged[middle];
        return (merged[middle - 1] + merged[middle]) / 2.0;
    }
}

