class Solution {
    public double findMedianSortedArrays(int[] nums1, int[] nums2) {
        if (nums1.length > nums2.length) {
            return findMedianSortedArrays(nums2, nums1);
        }
        int firstLength = nums1.length;
        int secondLength = nums2.length;
        int leftSize = (firstLength + secondLength + 1) / 2;
        int low = 0;
        int high = firstLength;
        while (low <= high) {
            int cutFirst = low + (high - low) / 2;
            int cutSecond = leftSize - cutFirst;
            int leftFirst = cutFirst == 0 ? Integer.MIN_VALUE : nums1[cutFirst - 1];
            int rightFirst = cutFirst == firstLength ? Integer.MAX_VALUE : nums1[cutFirst];
            int leftSecond = cutSecond == 0 ? Integer.MIN_VALUE : nums2[cutSecond - 1];
            int rightSecond = cutSecond == secondLength ? Integer.MAX_VALUE : nums2[cutSecond];
            if (leftFirst <= rightSecond && leftSecond <= rightFirst) {
                int leftMax = Math.max(leftFirst, leftSecond);
                if ((firstLength + secondLength) % 2 == 1) return leftMax;
                int rightMin = Math.min(rightFirst, rightSecond);
                return (leftMax + rightMin) / 2.0;
            }
            if (leftFirst > rightSecond) {
                high = cutFirst - 1;
            } else {
                low = cutFirst + 1;
            }
        }
        return 0.0;
    }
}
